<?php
require 'config/database.php';require 'includes/functions.php';$pageTitle='Gestión de préstamos';
if(isset($_GET['devolver'])){$s=$pdo->prepare("UPDATE prestamos SET estado='Devuelto', fecha_devolucion_real=CURDATE() WHERE prestamo_id=? AND estado='Prestado'");$s->execute([(int)$_GET['devolver']]);flash($s->rowCount()?'Devolución registrada correctamente.':'El préstamo ya estaba devuelto.',$s->rowCount()?'success':'error');redirect('prestamos.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){$libro=(int)($_POST['libro_id']??0);$miembro=(int)($_POST['miembro_id']??0);$fecha=$_POST['fecha_prestamo']??date('Y-m-d');$limite=$_POST['fecha_devolucion']??date('Y-m-d',strtotime('+14 days'));
if(!$libro||!$miembro||$limite<$fecha){flash('Seleccione un libro y un miembro, y verifique las fechas.','error');redirect('prestamos.php');}
$s=$pdo->prepare("SELECT COUNT(*) FROM prestamos WHERE libro_id=? AND estado='Prestado'");$s->execute([$libro]);if($s->fetchColumn()>0){flash('Este libro ya tiene un préstamo activo.','error');redirect('prestamos.php');}
$s=$pdo->prepare("INSERT INTO prestamos(libro_id,miembro_id,fecha_prestamo,fecha_devolucion,estado) VALUES(?,?,?,?,'Prestado')");$s->execute([$libro,$miembro,$fecha,$limite]);flash('Préstamo registrado correctamente.');redirect('prestamos.php');}
$books=$pdo->query("SELECT l.libro_id,l.titulo FROM libros l WHERE NOT EXISTS(SELECT 1 FROM prestamos p WHERE p.libro_id=l.libro_id AND p.estado='Prestado') ORDER BY l.titulo")->fetchAll();$members=$pdo->query("SELECT miembro_id,nombre,apellido FROM miembros ORDER BY nombre")->fetchAll();
$rows=$pdo->query("SELECT p.*,l.titulo,CONCAT(m.nombre,' ',m.apellido) miembro FROM prestamos p JOIN libros l ON l.libro_id=p.libro_id JOIN miembros m ON m.miembro_id=p.miembro_id ORDER BY p.prestamo_id DESC")->fetchAll();require 'includes/header.php';?>
<div class="section-head"><div><h3>Control de préstamos</h3><p>Registra salidas de libros y controla las devoluciones.</p></div><span class="count-pill"><?=count($rows)?> movimientos</span></div>
<div class="panel form-panel"><h3>Registrar nuevo préstamo</h3><?php if(!$books):?><div class="alert info">No hay libros disponibles. Registre un libro o espere una devolución.</div><?php endif;?><?php if(!$members):?><div class="alert info">Primero debe registrar al menos un miembro.</div><?php endif;?>
<form method="post" class="form-grid"><label>Libro disponible<select name="libro_id" required><option value="">Seleccione un libro</option><?php foreach($books as $b):?><option value="<?=$b['libro_id']?>"><?=e($b['titulo'])?></option><?php endforeach;?></select></label><label>Miembro<select name="miembro_id" required><option value="">Seleccione un miembro</option><?php foreach($members as $m):?><option value="<?=$m['miembro_id']?>"><?=e($m['nombre'].' '.$m['apellido'])?></option><?php endforeach;?></select></label><label>Fecha de préstamo<input type="date" name="fecha_prestamo" value="<?=date('Y-m-d')?>" required></label><label>Fecha prevista de devolución<input type="date" name="fecha_devolucion" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required></label><div class="form-actions"><button class="btn primary" <?=$books&&$members?'':'disabled'?>>＋ Registrar préstamo</button></div></form></div>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>Libro</th><th>Miembro</th><th>Préstamo</th><th>Devolución prevista</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">Todavía no hay préstamos registrados.</td></tr><?php endif;foreach($rows as $r):$late=$r['estado']==='Prestado'&&$r['fecha_devolucion']<date('Y-m-d');?><tr><td>#<?=$r['prestamo_id']?></td><td><b><?=e($r['titulo'])?></b></td><td><?=e($r['miembro'])?></td><td><?=e($r['fecha_prestamo'])?></td><td><?=e($r['fecha_devolucion'])?></td><td><span class="status <?=$r['estado']==='Devuelto'?'returned':($late?'late':'active')?>"><?=$r['estado']==='Devuelto'?'Devuelto':($late?'Vencido':'Prestado')?></span></td><td><?php if($r['estado']==='Prestado'):?><a class="action-button" data-confirm="¿Confirmar la devolución de este libro?" href="?devolver=<?=$r['prestamo_id']?>">Registrar devolución</a><?php else:?><span class="muted">Completado</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>